package com.dbproxy.driver

import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicLong
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

data class ConnectionState(
    val sessionId: String,
    val userId: String,
    val permissions: Set<String>,
    val lastVerified: Long,
    val queryCount: AtomicLong = AtomicLong(0)
)

class ProxyAuthenticator(private val hmacSecret: ByteArray) {
    private val activeSessions = ConcurrentHashMap<String, ConnectionState>()
    private val VERIFICATION_WINDOW_MS = 5000L

    fun createSession(sessionId: String, userId: String, permissions: Set<String>): ConnectionState {
        val state = ConnectionState(
            sessionId = sessionId,
            userId = userId,
            permissions = permissions,
            lastVerified = System.currentTimeMillis()
        )
        activeSessions[sessionId] = state
        return state
    }

    fun verifyAndGetPermissions(sessionId: String): Set<String>? {
        val state = activeSessions[sessionId] ?: return null
        return state.permissions
    }

    fun revokePermission(sessionId: String, permission: String) {
        activeSessions.computeIfPresent(sessionId) { _, current ->
            current.copy(permissions = current.permissions - permission)
        }
    }

    fun getSession(sessionId: String): ConnectionState? = activeSessions[sessionId]
}

class QueryRouter(private val authenticator: ProxyAuthenticator) {
    private val ADMIN_TABLES = setOf("users", "credentials", "audit_log", "system_config")
    // Sentinel permission that is never granted to any session; used to fail closed.
    private val DENY_PERMISSION = "__DENY__"

    fun routeQuery(sessionId: String, rawQuery: String): QueryResult {
        // Step 1: Fetch current session state atomically
        val currentState = authenticator.getSession(sessionId)
            ?: return QueryResult.Error("Invalid session")

        // Step 2: Parse the query to determine required permissions
        val requiredPermission = determineRequiredPermission(rawQuery)

        // Step 3: Check permission against the SAME state used for execution
        if (requiredPermission != null && requiredPermission !in currentState.permissions) {
            return QueryResult.Error("Insufficient permissions for: $requiredPermission")
        }

        // Step 4: Execute with the same state that was checked
        return executeQuery(rawQuery, currentState)
    }

    // Strip SQL comments so classification cannot be bypassed by comment prefixes.
    private fun stripComments(query: String): String {
        val noBlock = query.replace(Regex("/\\*.*?\\*/", RegexOption.DOT_MATCHES_ALL), " ")
        val noLine = noBlock.replace(Regex("--[^\\n]*"), " ")
        return noLine
    }

    private fun determineRequiredPermission(query: String): String? {
        val normalized = stripComments(query).trim().uppercase()
        val targetTable = extractTableName(normalized)

        return when {
            targetTable in ADMIN_TABLES && normalized.startsWith("SELECT") -> "ADMIN_READ"
            targetTable in ADMIN_TABLES -> "ADMIN_WRITE"
            normalized.startsWith("SELECT") -> "READ"
            normalized.startsWith("INSERT") || normalized.startsWith("UPDATE") -> "WRITE"
            normalized.startsWith("DELETE") -> "DELETE"
            normalized.startsWith("DROP") || normalized.startsWith("ALTER") -> "DDL"
            // Fail closed: any query we cannot classify requires a permission no session holds.
            else -> DENY_PERMISSION
        }
    }

    private fun extractTableName(query: String): String {
        val fromPattern = Regex("FROM\\s+(\\w+)", RegexOption.IGNORE_CASE)
        val intoPattern = Regex("INTO\\s+(\\w+)", RegexOption.IGNORE_CASE)
        val updatePattern = Regex("UPDATE\\s+(\\w+)", RegexOption.IGNORE_CASE)
        val tablePattern = Regex("TABLE\\s+(\\w+)", RegexOption.IGNORE_CASE)

        return fromPattern.find(query)?.groupValues?.get(1)?.lowercase()
            ?: intoPattern.find(query)?.groupValues?.get(1)?.lowercase()
            ?: updatePattern.find(query)?.groupValues?.get(1)?.lowercase()
            ?: tablePattern.find(query)?.groupValues?.get(1)?.lowercase()
            ?: ""
    }

    private fun executeQuery(query: String, state: ConnectionState): QueryResult {
        state.queryCount.incrementAndGet()
        // Simulated execution - in production this forwards to the actual DB
        return QueryResult.Success("Executed as ${state.userId} with perms: ${state.permissions}")
    }
}

sealed class QueryResult {
    data class Success(val message: String) : QueryResult()
    data class Error(val message: String) : QueryResult()
}

// Reverse proxy handler that processes incoming connections
class ReverseProxyHandler(private val router: QueryRouter, private val auth: ProxyAuthenticator) {

    fun handleRequest(sessionId: String, queryPayload: String): String {
        val result = router.routeQuery(sessionId, queryPayload)
        return when (result) {
            is QueryResult.Success -> "200 OK: ${result.message}"
            is QueryResult.Error -> "403 Denied: ${result.message}"
        }
    }

    fun handleAdminRevoke(sessionId: String, permission: String): String {
        auth.revokePermission(sessionId, permission)
        return "200 OK: Revoked $permission from $sessionId"
    }
}

fun main() {
    // Do not hardcode secrets; source from the environment.
    val secret = (System.getenv("PROXY_HMAC_SECRET")
        ?: error("PROXY_HMAC_SECRET environment variable must be set")).toByteArray()
    val auth = ProxyAuthenticator(secret)
    val router = QueryRouter(auth)
    val proxy = ReverseProxyHandler(router, auth)

    // Simulate: admin creates a session with elevated permissions
    auth.createSession("sess-001", "user42", setOf("READ", "WRITE", "ADMIN_READ"))

    // Normal query works
    println(proxy.handleRequest("sess-001", "SELECT * FROM users"))

    // Admin revokes ADMIN_READ
    println(proxy.handleAdminRevoke("sess-001", "ADMIN_READ"))

    // Query now correctly fails
    println(proxy.handleRequest("sess-001", "SELECT * FROM users"))
}
